/**
 * Single-scalar-output task kinds whose EDK factory exposes the result as
 * `output` (`ActionDef<{ output: unknown }>`), but whose platform wire name
 * differs. aiSummarize/aiTransform were "confirmed against real pulled wire
 * data" per the original note, naming their output `response`; documentModel
 * (rawText data source) names it `text`. aiClassify's `Response` is confirmed
 * directly against a live-deployed task's own `refs` map (Preston High
 * integration run, item 235) — that map is Title-Case (`Reason`, `Response`,
 * `Success`), so the wire name here must match that casing exactly, not the
 * lowercase property name. aiSummarize/aiTransform share the same Title-Case
 * refs map (`Response`, `Success`) — confirmed live via apply failures when
 * downstream tasks referenced `.output` with the old lowercase wire name.
 *
 * Used by `build.ts` (forward: `output` → wire name) and `from-tf.ts`
 * (inverse: wire name → `output`) — kept dependency-free so importing it from
 * either side can never introduce a cycle.
 */
export const OUTPUT_KEY_WIRE_NAME = {
    aiSummarize: "Response",
    aiTransform: "Response",
    aiClassify: "Response",
    documentModel: "text",
};
/**
 * apiRequest task outputs in authoring use camelCase segments (`statusCode`,
 * `file.content`, …) but the provider refs map uses display labels — confirmed
 * live on Sanofi saveAttachment (FILE) and Deloitte demoapptwo (CUSTOM).
 */
export const API_TASK_REF_WIRE_NAMES = {
    statusCode: "API Response Status Code",
    textResponse: "API Response (text)",
    response: "Response",
    file: "File",
    "file.content": "Content",
    "file.contentType": "Content Type",
    "file.name": "Name",
};
/** Inverse of {@link API_TASK_REF_WIRE_NAMES} for export jsonencode envelopes. */
export const API_TASK_REF_AUTHORING_NAMES = Object.fromEntries(Object.entries(API_TASK_REF_WIRE_NAMES).map(([authoring, wire]) => [wire, authoring]));
/**
 * Resolve a single `elementum_api_task` refs[] wire label (e.g. "File",
 * "Content Type") to its authoring path segments (e.g. ["file"], ["file",
 * "contentType"]) via {@link API_TASK_REF_AUTHORING_NAMES} — some authoring
 * names are dotted (`file.content`) since they nest under the `file` output.
 * Returns undefined for a wire label with no known authoring counterpart so
 * callers can fall back to the generic segment mapping.
 */
export function apiTaskRefAuthoringPath(wireSegment) {
    const authoring = API_TASK_REF_AUTHORING_NAMES[wireSegment];
    return authoring !== undefined ? authoring.split(".") : undefined;
}
